#include <iostream>
#include <string>
#include <vector>
#include "../idna.hpp"

int main(int argc, char* argv[]) {
    std::vector<std::string> inputs;

    if (argc > 1) {
        for (int i = 1; i < argc; i++) {
            inputs.push_back(argv[i]);
        }
    } else {
        inputs = {"one", "two.three", "four.five.six"};
    }

    // 调用11个不同的API
    for (const auto& input : inputs) {
        std::cout << idna::to_ascii(input) << " ";
        std::cout << idna::to_unicode(input) << " ";
        std::cout << idna::punycode_encode(input) << " ";
        std::cout << idna::punycode_decode(input) << " ";
        std::cout << idna::is_valid_domain(input) << " ";
        std::cout << idna::is_valid_label(input) << " ";
        std::cout << idna::is_ascii_domain(input) << " ";
        std::cout << idna::is_idn_domain(input) << " ";
        std::cout << idna::to_lower(input) << " ";
        std::cout << idna::normalize(input) << " ";
        std::cout << idna::count_labels(input) << std::endl;
    }

    return 0;
}


